import subprocess
# Check which page the bibliography starts on
result = subprocess.run(['pdftotext', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
pages = text.split('\f')
for i, page in enumerate(pages):
    if 'References' in page and 'bibliography' not in page.lower():
        # Check if this looks like the references section
        lines = [l.strip() for l in page.split('\n') if l.strip()]
        for j, line in enumerate(lines):
            if line == 'References':
                print(f'References section starts on page {i+1}')
                break
    if 'Limitations' in page:
        lines = [l.strip() for l in page.split('\n') if l.strip()]
        for j, line in enumerate(lines):
            if 'Limitations' == line:
                print(f'Limitations on page {i+1}')
                break
    if i < 10:
        first_line = page.strip().split('\n')[0] if page.strip() else ''
        print(f'Page {i+1}: {first_line[:80]}')
"
